export const base='/engine/api/review-sessions';
export const id=value=>{if(!/^[A-Za-z0-9_-]+$/.test(String(value)))throw Error('无效会话或附件编号');return encodeURIComponent(value);};
export function validateSnapshot(s){if(s?.schema_version!=='session-1.0'||!s.session_id||!Number.isInteger(s.context_version)||!Array.isArray(s.findings)||!Array.isArray(s.evidence))throw Error('会话响应不符合 session-1.0');return s;}
export function makeEvent(s,type,payload,actor,eventId=crypto.randomUUID()){return {event_id:eventId,expected_context_version:s.context_version,type,payload,actor:actor.trim()||'unknown'};}
export async function json(path='',options={}){let res;try{res=await fetch(base+path,{...options,signal:AbortSignal.timeout(30000),headers:{'Content-Type':'application/json',...options.headers}});}catch{throw Error('无法连接会话后端，请检查新版服务；请求结果不明时先刷新会话再重试');}const data=await res.json();if(!res.ok){const e=Error(data.error?.message||data.detail?.[0]?.msg||('接口错误 '+res.status));e.status=res.status;throw e;}return data;}
export const api={capabilities:()=>json('/capabilities'),create:async input=>validateSnapshot(await json('',{method:'POST',body:JSON.stringify(input)})),get:async sid=>validateSnapshot(await json('/'+id(sid))),updates:(s)=>json('/'+id(s.session_id)+'/updates?after_sequence='+s.sequence),event:async(s,event)=>validateSnapshot(await json('/'+id(s.session_id)+'/events',{method:'POST',body:JSON.stringify(event)})),report:async(s,v)=>validateSnapshot(await json('/'+id(s.session_id)+'/reports/'+Number(v)))};
export function artifact(s,aid){return base+'/'+id(s.session_id)+'/artifacts/'+id(aid);}
export function download(s,kind,version){const q=new URLSearchParams();if(version>0)q.set('version',version);let endpoint=kind==='zip'?'package':kind==='json'?'structured-report':'export';if(['human','summary','audit'].includes(kind))q.set('format',kind);return base+'/'+id(s.session_id)+'/'+endpoint+'?'+q;}
export function validateSource(source){if(['website','figma_board','figma_prototype'].includes(source.kind)||source.reference){let u;try{u=new URL(source.reference);}catch{throw Error('链接需填写完整 https:// 地址；上传本地文件时链接可留空，不要填写序号或文件名');}if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('材料链接须为不含账号密码的 HTTP(S) 地址');if(source.kind.startsWith('figma_')&&!['figma.com','www.figma.com'].includes(u.hostname))throw Error('请选择 figma.com 链接');}if(source.kind==='document'&&!source.content&&!source.document_base64&&!source.reference)throw Error('请填写文档或选择文件');if(source.kind==='image'&&!source.image_base64)throw Error('请选择图片');return source;}

export function fileSourceKind(file){if(['image/png','image/jpeg','image/webp'].includes(file.type)||/\.(png|jpe?g|webp)$/i.test(file.name))return 'image';if(/\.(pdf|docx|txt|md|html?|csv)$/i.test(file.name))return 'document';throw Error('文件格式暂不支持，请选择 PDF、DOCX、文本或 PNG/JPG/WebP 图片');}
